import React, { useState, useEffect } from "react";
import { auth, db } from "../firebase";
import { createUserWithEmailAndPassword, signInWithEmailAndPassword, sendPasswordResetEmail } from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import { FiUser, FiMail, FiLock, FiEye, FiEyeOff, FiArrowRight } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { sendSignInLinkToEmail, isSignInWithEmailLink, signInWithEmailLink } from "firebase/auth";
import Popup from "./Popup";
import logo from "../assets/logo.png";

const AuthForm = () => {
  const [isEmailLinkMode, setIsEmailLinkMode] = useState(false);
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [gender, setGender] = useState("Male");
  const [showPassword, setShowPassword] = useState(false);
  const [formErrors, setFormErrors] = useState({});
  const [message, setMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showSuccessPopup, setShowSuccessPopup] = useState(false);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [error, setError] = useState("");

  const navigate = useNavigate();

  const actionCodeSettings = {
    url: "https://zane-fit.vercel.app/",
    handleCodeInApp: true,
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { 
      opacity: 1,
      transition: { staggerChildren: 0.1 }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: { type: "spring", stiffness: 100 }
    }
  };

  useEffect(() => {
    if (isSignInWithEmailLink(auth, window.location.href)) {
      const storedEmail = window.localStorage.getItem("emailForSignIn");
      if (storedEmail) {
        signInWithEmailLink(auth, storedEmail, window.location.href)
          .then((result) => {
            window.localStorage.removeItem("emailForSignIn");
            setMessage("Successfully signed in!");
            setShowSuccessPopup(true);
          })
          .catch((error) => {
            setError("Failed to sign in: " + error.message);
          });
      }
    }
  }, []);

  const sendEmailLink = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");
    setIsLoading(true);

    if (!email.trim()) {
      setFormErrors({ email: "Email is required" });
      setIsLoading(false);
      return;
    }

    try {
      await sendSignInLinkToEmail(auth, email, actionCodeSettings);
      window.localStorage.setItem("emailForSignIn", email);
      setMessage("Email sent! Check your inbox.");
    } catch (err) {
      setError(err.message.replace("Firebase: ", ""));
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage("");
    setError("");

    if (!email.trim()) {
      setError("Email is required");
      setIsLoading(false);
      return;
    }

    try {
      await sendPasswordResetEmail(auth, email);
      setMessage("Password reset email sent. Please check your inbox.");
      setTimeout(() => {
        setIsForgotPassword(false);
        setMessage("");
      }, 3000);
    } catch (err) {
      setError(err.message.replace("Firebase: ", ""));
    } finally {
      setIsLoading(false);
    }
  };

  const validateForm = () => {
    const errors = {};
    
    if (!email.trim()) {
      errors.email = "Email is required";
    } else if (!/^\S+@\S+\.\S+$/.test(email)) {
      errors.email = "Please enter a valid email";
    }
    
    if (!password) {
      errors.password = "Password is required";
    } else if (password.length < 6) {
      errors.password = "Password must be at least 6 characters";
    }
    
    if (!isLogin) {
      if (!name.trim()) {
        errors.name = "Name is required";
      }
    }
    
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAuth = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage("");

    if (!validateForm()) {
      setIsLoading(false);
      return;
    }

    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
        setMessage("Logged in successfully!");
        setShowSuccessPopup(true);
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const user = userCredential.user;

        await setDoc(doc(db, "users", user.uid), {
          name,
          gender,
          email,
          createdAt: new Date()
        });

        setMessage("Account created successfully!");
        setShowSuccessPopup(true);
      }
    } catch (error) {
      let errorMessage = error.message.replace("Firebase: ", "");
      
      switch(error.code) {
        case "auth/user-not-found":
          errorMessage = "No account found with this email";
          setFormErrors({ ...formErrors, email: errorMessage });
          break;
        case "auth/wrong-password":
          errorMessage = "Incorrect password";
          setFormErrors({ ...formErrors, password: errorMessage });
          break;
        case "auth/email-already-in-use":
          errorMessage = "Email already in use";
          setFormErrors({ ...formErrors, email: errorMessage });
          break;
        case "auth/weak-password":
          errorMessage = "Password should be at least 6 characters";
          setFormErrors({ ...formErrors, password: errorMessage });
          break;
        default:
          errorMessage = "An error occurred. Please try again.";
      }
      
      setMessage(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (showSuccessPopup) {
      const timer = setTimeout(() => {
        navigate("/");
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [showSuccessPopup, navigate]);

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setMessage("");
    setFormErrors({});
    setShowSuccessPopup(false);
    setIsForgotPassword(false);
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  const handleForgotPasswordClick = () => {
    setIsForgotPassword(true);
    setMessage("");
    setError("");
    setFormErrors({});
  };

  if (isEmailLinkMode) {
    return (
      <div style={styles.container}>
        <motion.div style={styles.card}>
          <div style={styles.header}>
            <div style={styles.logoContainer}>
              <img src={logo} alt="App Logo" style={styles.logo} />
            </div>
            <h2 style={styles.title}>Sign in with Email Link</h2>
            <p style={styles.subtitle}>Enter your email to receive a sign-in link</p>
          </div>

          <form onSubmit={sendEmailLink} style={styles.form}>
            <div style={styles.inputGroup}>
              <div style={styles.inputIcon}>
                <FiMail />
              </div>
              <input
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                style={{ ...styles.input, ...(formErrors.email && styles.inputError) }}
              />
            </div>
            {formErrors.email && <p style={styles.errorText}>{formErrors.email}</p>}

            <button
              type="submit"
              style={{ ...styles.submitButton, opacity: isLoading ? 0.7 : 1 }}
              disabled={isLoading}
            >
              {isLoading ? "Sending..." : "Send Sign-in Link"}
            </button>

            <button
              type="button"
              onClick={() => {
                setIsEmailLinkMode(false);
                setFormErrors({});
                setMessage("");
                setError("");
              }}
              style={styles.secondaryButton}
            >
              Back
            </button>

            {message && <p style={styles.successMessage}>{message}</p>}
            {error && <p style={styles.errorMessage}>{error}</p>}
          </form>
        </motion.div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <motion.div 
        style={styles.card}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
      >
        <div style={styles.header}>
          <div style={styles.logoContainer}>
            <img src={logo} alt="App Logo" style={styles.logo} />
          </div>
          <h1 style={styles.title}>
            {isForgotPassword ? "Reset Password" : isLogin ? "Welcome Back" : "Create Account"}
          </h1>
          <p style={styles.subtitle}>
            {isForgotPassword 
              ? "Enter your email to receive a reset link" 
              : isLogin 
                ? "Sign in to continue your journey" 
                : "Join us to get started"}
          </p>
        </div>

        {isForgotPassword ? (
          <motion.form 
            onSubmit={handleResetPassword} 
            style={styles.form}
            variants={containerVariants}
            initial="hidden"
            animate="visible"
          >
            <motion.div variants={itemVariants}>
              <div style={styles.inputGroup}>
                <div style={styles.inputIcon}>
                  <FiMail />
                </div>
                <input
                  type="email"
                  placeholder="Email Address"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  style={{ ...styles.input, ...(formErrors.email && styles.inputError) }}
                />
              </div>
              {formErrors.email && <p style={styles.errorText}>{formErrors.email}</p>}
            </motion.div>

            <motion.div variants={itemVariants}>
              <button 
                type="submit" 
                style={{
                  ...styles.submitButton,
                  opacity: isLoading ? 0.8 : 1,
                }}
                disabled={isLoading}
              >
                <span>{isLoading ? "Sending..." : "Send Reset Link"}</span>
                {!isLoading && <FiArrowRight style={styles.arrowIcon} />}
              </button>
            </motion.div>

            <motion.div variants={itemVariants}>
              <button 
                type="button" 
                onClick={() => setIsForgotPassword(false)}
                style={styles.secondaryButton}
              >
                Back to {isLogin ? "Sign In" : "Sign Up"}
              </button>
            </motion.div>

            {error && (
              <motion.div 
                style={styles.errorMessage}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
              >
                {error}
              </motion.div>
            )}

            {message && (
              <motion.div 
                style={styles.successMessage}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
              >
                {message}
              </motion.div>
            )}
          </motion.form>
        ) : (
          <motion.form 
            onSubmit={handleAuth} 
            style={styles.form}
            variants={containerVariants}
            initial="hidden"
            animate="visible"
          >
            {!isLogin && (
              <>
                <motion.div variants={itemVariants}>
                  <div style={styles.inputGroup}>
                    <div style={styles.inputIcon}>
                      <FiUser />
                    </div>
                    <input
                      type="text"
                      placeholder="Full Name"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      style={{ ...styles.input, ...(formErrors.name && styles.inputError) }}
                    />
                  </div>
                  {formErrors.name && <p style={styles.errorText}>{formErrors.name}</p>}
                </motion.div>

                <motion.div variants={itemVariants}>
                  <div style={styles.inputGroup}>
                    <select
                      value={gender}
                      onChange={(e) => setGender(e.target.value)}
                      style={{ ...styles.input, ...styles.select }}
                    >
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                      <option value="Other">Other</option>
                      <option value="Prefer not to say">Prefer not to say</option>
                    </select>
                  </div>
                </motion.div>
              </>
            )}

            <motion.div variants={itemVariants}>
              <div style={styles.inputGroup}>
                <div style={styles.inputIcon}>
                  <FiMail />
                </div>
                <input
                  type="email"
                  placeholder="Email Address"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  style={{ ...styles.input, ...(formErrors.email && styles.inputError) }}
                />
              </div>
              {formErrors.email && <p style={styles.errorText}>{formErrors.email}</p>}
            </motion.div>

            <motion.div variants={itemVariants}>
              <div style={styles.inputGroup}>
                <div style={styles.inputIcon}>
                  <FiLock />
                </div>
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  style={{ ...styles.input, ...(formErrors.password && styles.inputError) }}
                />
                <button 
                  type="button" 
                  onClick={togglePasswordVisibility} 
                  style={styles.passwordToggle}
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <FiEyeOff /> : <FiEye />}
                </button>
              </div>
              {formErrors.password && <p style={styles.errorText}>{formErrors.password}</p>}
            </motion.div>

            {isLogin && (
              <motion.div variants={itemVariants} style={styles.forgotPassword}>
                <button
                  type="button"
                  style={styles.forgotPasswordButton}
                  onClick={handleForgotPasswordClick}
                >
                  Forgot Password?
                </button>
              </motion.div>
            )}

            <motion.div variants={itemVariants}>
              <button 
                type="submit" 
                style={{
                  ...styles.submitButton,
                  opacity: isLoading ? 0.8 : 1,
                }}
                disabled={isLoading}
              >
                <span>{isLoading ? "Processing..." : isLogin ? "Sign In" : "Sign Up"}</span>
                {!isLoading && <FiArrowRight style={styles.arrowIcon} />}
              </button>
            </motion.div>
          </motion.form>
        )}

        {!isForgotPassword && (
          <motion.div 
            style={styles.footer}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3 }}
          >
            <p style={styles.footerText}>
              {isLogin ? "Don't have an account?" : "Already have an account?"}
              <button 
                type="button" 
                onClick={toggleMode} 
                style={styles.toggleButton}
              >
                {isLogin ? " Sign Up" : " Sign In"}
              </button>
            </p>
            <p style={{ ...styles.footerText, marginTop: 10 }}>
              Or&nbsp;
              <button
                onClick={() => {
                  setIsEmailLinkMode(true);
                  setIsLogin(false);
                  setIsForgotPassword(false);
                  setFormErrors({});
                  setMessage("");
                }}
                style={styles.toggleButton}
              >
                Sign in via email link
              </button>
            </p>
          </motion.div>
        )}

        <AnimatePresence>
          {message && !showSuccessPopup && !isForgotPassword && (
            <motion.div
              style={{ 
                ...styles.message, 
                ...(message.includes("successfully") ? styles.successMessage : styles.errorMessage) 
              }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
            >
              {message}
            </motion.div>
          )}
        </AnimatePresence>

        {showSuccessPopup && (
          <Popup
            show={showSuccessPopup}
            onClose={() => setShowSuccessPopup(false)}
            title="Success"
            message={message}
            color="#10b981"
          />
        )}
      </motion.div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#f8fafc",
    padding: "20px",
    backgroundImage: "linear-gradient(135deg, #f5f7fa 0%, #e4e8f0 100%)",
  },
  card: {
    width: "100%",
    maxWidth: "440px",
    backgroundColor: "#ffffff",
    borderRadius: "16px",
    boxShadow: "0 10px 30px rgba(0, 0, 0, 0.08)",
    padding: "40px 32px",
    position: "relative",
    overflow: "hidden",
  },
  logoContainer: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "24px",
  },
  logo: {
    height: "48px",
    width: "auto",
  },
  header: {
    marginBottom: "32px",
    textAlign: "center",
  },
  title: {
    fontSize: "26px",
    fontWeight: "700",
    color: "#1e293b",
    marginBottom: "8px",
    letterSpacing: "-0.5px",
  },
  subtitle: {
    fontSize: "14px",
    color: "#64748b",
    margin: "0",
    lineHeight: "1.5",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "20px",
  },
  inputGroup: {
    position: "relative",
    display: "flex",
    alignItems: "center",
  },
  inputIcon: {
    position: "absolute",
    left: "14px",
    color: "#94a3b8",
    fontSize: "18px",
  },
  input: {
    width: "100%",
    padding: "14px 14px 14px 42px",
    fontSize: "15px",
    borderRadius: "10px",
    border: "1px solid #e2e8f0",
    backgroundColor: "#f8fafc",
    outline: "none",
    fontFamily: "inherit",
    transition: "all 0.2s ease",
  },
  select: {
    padding: "14px",
    appearance: "none",
    paddingLeft: "16px",
  },
  passwordToggle: {
    position: "absolute",
    right: "12px",
    background: "none",
    border: "none",
    color: "#94a3b8",
    cursor: "pointer",
    padding: "4px",
    display: "flex",
    alignItems: "center",
    fontSize: "18px",
    transition: "color 0.2s ease",
  },
  inputError: {
    borderColor: "#ef4444",
    backgroundColor: "#fef2f2",
  },
  errorText: {
    fontSize: "13px",
    color: "#ef4444",
    marginTop: "6px",
    marginLeft: "8px",
  },
  forgotPassword: {
    display: "flex",
    justifyContent: "flex-end",
    marginTop: "-8px",
  },
  forgotPasswordButton: {
    background: "none",
    border: "none",
    color: "#64748b",
    fontSize: "13px",
    cursor: "pointer",
    fontWeight: "500",
    transition: "color 0.2s ease",
    padding: "4px",
    '&:hover': {
      color: "#4f46e5",
    }
  },
  submitButton: {
    padding: "14px",
    backgroundColor: "#4f46e5",
    color: "white",
    border: "none",
    borderRadius: "10px",
    fontWeight: "600",
    cursor: "pointer",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    gap: "8px",
    fontSize: "15px",
    marginTop: "8px",
    transition: "all 0.2s ease",
    boxShadow: "0 4px 6px rgba(79, 70, 229, 0.1)",
    '&:hover': {
      backgroundColor: "#4338ca",
    }
  },
  secondaryButton: {
    padding: "14px",
    backgroundColor: "transparent",
    color: "#4f46e5",
    border: "1px solid #e2e8f0",
    borderRadius: "10px",
    fontWeight: "600",
    cursor: "pointer",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    gap: "8px",
    fontSize: "15px",
    marginTop: "8px",
    transition: "all 0.2s ease",
    width: "100%",
    '&:hover': {
      backgroundColor: "#f1f5f9",
    }
  },
  arrowIcon: {
    fontSize: "18px",
  },
  footer: {
    marginTop: "24px",
    textAlign: "center",
    paddingTop: "16px",
    borderTop: "1px solid #f1f5f9",
  },
  footerText: {
    fontSize: "14px",
    color: "#64748b",
  },
  toggleButton: {
    background: "none",
    border: "none",
    color: "#4f46e5",
    fontWeight: "600",
    cursor: "pointer",
    marginLeft: "4px",
    transition: "all 0.2s ease",
    padding: "0",
    '&:hover': {
      textDecoration: "underline",
    }
  },
  message: {
    padding: "14px",
    borderRadius: "10px",
    marginTop: "16px",
    fontSize: "14px",
    textAlign: "center",
    fontWeight: "500",
  },
  successMessage: {
    backgroundColor: "#ecfdf5",
    color: "#065f46",
    border: "1px solid #a7f3d0",
  },
  errorMessage: {
    backgroundColor: "#fef2f2",
    color: "#991b1b",
    border: "1px solid #fecaca",
  },
};

export default AuthForm;