import React, { useState } from 'react';
import axios from 'axios';
import './NutritionGuide.css';
import Header from './Header'; // Import your Header component

const NutritionGuidance = () => {
  const [formData, setFormData] = useState({
    age: '',
    weight: '',
    height: '',
    bodyType: 'ectomorph',
    activityLevel: 'moderate',
    gender: 'male',
    goals: 'maintenance'
  });

  const [loading, setLoading] = useState(false);
  const [recommendations, setRecommendations] = useState(null);
  const [error, setError] = useState(null);

  const bodyTypes = [
    { value: 'ectomorph', label: 'Ectomorph (Lean)' },
    { value: 'mesomorph', label: 'Mesomorph (Muscular)' },
    { value: 'endomorph', label: 'Endomorph (Stocky)' }
  ];

  const activityLevels = [
    { value: 'sedentary', label: 'Sedentary (little or no exercise)' },
    { value: 'light', label: 'Light (exercise 1-3 days/week)' },
    { value: 'moderate', label: 'Moderate (exercise 3-5 days/week)' },
    { value: 'active', label: 'Active (exercise 6-7 days/week)' },
    { value: 'very_active', label: 'Very Active (hard exercise daily)' }
  ];

  const goals = [
    { value: 'weight_loss', label: 'Weight Loss' },
    { value: 'maintenance', label: 'Maintenance' },
    { value: 'muscle_gain', label: 'Muscle Gain' }
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const calculateNutrition = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await axios.post('https://zanefit-express-production.up.railway.app/api/nutrition/calculate', formData);
      setRecommendations(response.data);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to calculate nutrition');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
    <Header />
    <div className="nutrition-guidance-container">
     
      <h1>Under Development</h1>
      <h2>Personalized Nutrition Guidance</h2>
      
      <form onSubmit={calculateNutrition} className="nutrition-form">
        <div className="form-group">
          <label>Age (years)</label>
          <input
            type="number"
            name="age"
            value={formData.age}
            onChange={handleChange}
            min="18"
            max="100"
            required
          />
        </div>

        <div className="form-group">
          <label>Weight (kg)</label>
          <input
            type="number"
            name="weight"
            value={formData.weight}
            onChange={handleChange}
            min="40"
            max="200"
            step="0.1"
            required
          />
        </div>

        <div className="form-group">
          <label>Height (cm)</label>
          <input
            type="number"
            name="height"
            value={formData.height}
            onChange={handleChange}
            min="140"
            max="220"
            required
          />
        </div>

        <div className="form-group">
          <label>Gender</label>
          <div className="radio-group">
            <label>
              <input
                type="radio"
                name="gender"
                value="male"
                checked={formData.gender === 'male'}
                onChange={handleChange}
              />
              Male
            </label>
            <label>
              <input
                type="radio"
                name="gender"
                value="female"
                checked={formData.gender === 'female'}
                onChange={handleChange}
              />
              Female
            </label>
          </div>
        </div>

        <div className="form-group">
          <label>Body Type</label>
          <select
            name="bodyType"
            value={formData.bodyType}
            onChange={handleChange}
          >
            {bodyTypes.map(type => (
              <option key={type.value} value={type.value}>
                {type.label}
              </option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>Activity Level</label>
          <select
            name="activityLevel"
            value={formData.activityLevel}
            onChange={handleChange}
          >
            {activityLevels.map(level => (
              <option key={level.value} value={level.value}>
                {level.label}
              </option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>Goals</label>
          <select
            name="goals"
            value={formData.goals}
            onChange={handleChange}
          >
            {goals.map(goal => (
              <option key={goal.value} value={goal.value}>
                {goal.label}
              </option>
            ))}
          </select>
        </div>

        <button type="submit" disabled={loading}>
          {loading ? 'Calculating...' : 'Get Nutrition Plan'}
        </button>

        {error && <div className="error-message">{error}</div>}
      </form>

      {recommendations && (
        <div className="nutrition-results">
          <h3>Your Personalized Nutrition Plan</h3>
          
          <div className="macros-summary">
            <h4>Daily Macronutrients</h4>
            <div className="macros-grid">
              <div className="macro-card">
                <h5>Calories</h5>
                <p>{recommendations.calories} kcal</p>
              </div>
              <div className="macro-card">
                <h5>Protein</h5>
                <p>{recommendations.protein}g ({recommendations.proteinPercentage}%)</p>
              </div>
              <div className="macro-card">
                <h5>Carbs</h5>
                <p>{recommendations.carbs}g ({recommendations.carbsPercentage}%)</p>
              </div>
              <div className="macro-card">
                <h5>Fats</h5>
                <p>{recommendations.fats}g ({recommendations.fatsPercentage}%)</p>
              </div>
            </div>
          </div>

          <div className="meal-plan">
            <h4>Sample Meal Plan</h4>
            {recommendations.meals.map((meal, index) => (
              <div key={index} className="meal-card">
                <h5>{meal.time}: {meal.name}</h5>
                <ul>
                  {meal.items.map((item, i) => (
                    <li key={i}>{item}</li>
                  ))}
                </ul>
                <p className="meal-calories">~{meal.calories} kcal</p>
              </div>
            ))}
          </div>

          <div className="nutrition-tips">
            <h4>Nutrition Tips for Your Body Type</h4>
            <ul>
              {recommendations.tips.map((tip, index) => (
                <li key={index}>{tip}</li>
              ))}
            </ul>
          </div>
        </div>
      )}
    </div>
    </>
  );
};

export default NutritionGuidance;