import React from "react";
import { useNavigate } from "react-router-dom";
import "./FeaturesList.css";
import training from "../assets/training.webp";
import diet from "../assets/diet.webp";
import progress from "../assets/progress.webp";
import equipment from "../assets/equipment.webp";
import Header from "./Header"; // Import your Header component

const features = [
  {
    title: "Workout Planner",
    description: "Get your free personalized workout plan.",
    image: training,
    route: "/workout-form",
    accentColor: "rgba(255, 105, 97, 0.8)"
  },
  {
    title: "Nutrition Guidance",
    description: "Learn what and how much to eat based on your goals.",
    image: diet,
    route: "/nutrition",
    accentColor: "rgba(97, 205, 153, 0.8)"
  },
  {
    title: "Progress Tracker",
    description: "Track your progress and stay consistent.",
    image: progress,
    route: "/progress",
    accentColor: "rgba(97, 160, 255, 0.8)"
  },
  {
    title: "Equipment Suggestions",
    description: "Plans tailored to equipment you have.",
    image: equipment,
    route: "/equipment",
    accentColor: "rgba(255, 179, 71, 0.8)"
  },
];

const FeatureList = () => {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = React.useState(false);

  const handleCardClick = (route) => {
    navigate(route);
  };

  // const toggleMenu = () => {
  //   setMenuOpen(!menuOpen);
  // };

  return (
    <div className="features-app">
      <Header/>

      <div className="features-wrapper">
        <div className="features-header">
          <h1 className="features-title">Explore ZaNeFiT Features</h1>
          <p className="features-subtitle">Discover tools to transform your fitness journey</p>
        </div>
        <div className="features-grid">
          {features.map((feature, index) => (
            <div
              key={index}
              className="feature-card"
              style={{ 
                "--accent-color": feature.accentColor,
                backgroundImage: `linear-gradient(to bottom, rgba(0,0,0,0.1), ${feature.accentColor}), url(${feature.image})`
              }}
              onClick={() => handleCardClick(feature.route)}
            >
              <div className="feature-overlay">
                <div className="feature-number">0{index + 1}</div>
                <h2>{feature.title}</h2>
                <p>{feature.description}</p>
                <div className="feature-cta">
                  Get Started
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M5 12H19M19 12L12 5M19 12L12 19" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default FeatureList;