import React, { useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import HomePage from './Components/Homepage';
import WorkoutForm from './Components/WorkoutForm';
import FeaturesList from './Components/FeaturesList'; 
import NutritionGuide from './Components/NutritionGuide';
import ProgressTracker from './Components/ProgressTracker';
import Equipment from './Components/Equipment';
import PhoneAuthForm from './Components/PhoneAuthForm';
import Admin from './Components/Admin'; // Your AdminDashboard component
import PasswordProtectedRoute from './Components/PasswordProtectedRoute'; 
import UserDashboard from './Components/UserDashboard';
import PrivateRoute from "./Components/PrivateRoute";

import AOS from 'aos';
import 'aos/dist/aos.css';

function App() {
  // Initialize AOS
  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-in-out',
      once: true
    });
  }, []);

  return (
    <Router>
    <Routes>
      <Route path="/auth" element={<PhoneAuthForm />} />
      <Route path="/login" element={<PhoneAuthForm />} />
      <Route path="/signup" element={<PhoneAuthForm />} />
      <Route path="/" element={<HomePage />} />
      <Route
        path="/admin"
        element={<PasswordProtectedRoute element={Admin} />}
      />
  
      {/* Protected Routes */}
      <Route
        path="/workout-form"
        element={
          <PrivateRoute>
            <WorkoutForm />
          </PrivateRoute>
        }
      />
      <Route
        path="/featuresList"
        element={
          <PrivateRoute>
            <FeaturesList />
          </PrivateRoute>
        }
      />
      <Route
        path="/nutrition"
        element={
          <PrivateRoute>
            <NutritionGuide />
          </PrivateRoute>
        }
      />
      <Route
        path="/progress"
        element={
          <PrivateRoute>
            <ProgressTracker />
          </PrivateRoute>
        }
      />
      <Route
        path="/equipment"
        element={
          <PrivateRoute>
            <Equipment />
          </PrivateRoute>
        }
      />
      <Route
        path="/UserDashboard"
        element={
          <PrivateRoute>
            <UserDashboard />
          </PrivateRoute>
        }
      />
    </Routes>
  </Router>
  
  );
}

export default App;