// components/Popup.js
import React from "react";
import { FiCheckCircle, FiX } from "react-icons/fi";
import { motion, AnimatePresence } from "framer-motion";
import styled, { keyframes } from "styled-components";

const Popup = ({ show, onClose, title, message, icon, color = "#10b981" }) => {
  return (
    <AnimatePresence>
      {show && (
        <PopupOverlay
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
        >
          <PopupContent
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.9, opacity: 0 }}
          >
            <CloseButton onClick={onClose}>
              <FiX />
            </CloseButton>
            <SuccessIcon style={{ color }}>
              {icon || <FiCheckCircle />}
            </SuccessIcon>
            <PopupTitle>{title}</PopupTitle>
            <PopupText>{message}</PopupText>
            <LoadingBar>
              <LoadingProgress />
            </LoadingBar>
          </PopupContent>
        </PopupOverlay>
      )}
    </AnimatePresence>
  );
};

export default Popup;

// styled components stay the same as your original code
const fadeIn = keyframes`
  from { opacity: 0; }
  to { opacity: 1; }
`;

const loading = keyframes`
  from { width: 0%; }
  to { width: 100%; }
`;

const PopupOverlay = styled(motion.div)`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopupContent = styled(motion.div)`
  background-color: white;
  padding: 2.5rem;
  border-radius: 1rem;
  text-align: center;
  max-width: 400px;
  width: 90%;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 16px;
  right: 16px;
  background: none;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  font-size: 1.25rem;

  &:hover {
    color: #4f46e5;
  }
`;

const SuccessIcon = styled.div`
  font-size: 3rem;
  margin-bottom: 1rem;
  display: flex;
  justify-content: center;
`;

const PopupTitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: #1e293b;
`;

const PopupText = styled.p`
  color: #64748b;
  margin-bottom: 1.5rem;
`;

const LoadingBar = styled.div`
  height: 6px;
  background-color: #e2e8f0;
  border-radius: 3px;
  overflow: hidden;
  margin-top: 1rem;
`;

const LoadingProgress = styled.div`
  height: 100%;
  width: 100%;
  background-color: #10b981;
  animation: ${loading} 2s linear forwards;
`;
