import React, { useState } from 'react';
import axios from 'axios';
import { Helmet } from 'react-helmet';
import Header from './Header'; // Import your Header component
import './WorkoutForm.css';

const WorkoutForm = () => {
  const [formData, setFormData] = useState({
    age: '',
    height: '',
    weight: '',
    gender: 'male',
    goal: 'build muscle',
    equipment: 'basic',
    fitnessLevel: 'beginner',
    workoutDays: 3,
    workoutDuration: 30,
    injuries: '',
    preferences: ''
  });

  const [workoutPlan, setWorkoutPlan] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  // const [menuOpen, setMenuOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('summary'); // For workout plan tabs

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // const toggleMenu = () => {
  //   setMenuOpen(!menuOpen);
  // };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    const payload = {
      age: Number(formData.age),
      height: Number(formData.height),
      weight: Number(formData.weight),
      gender: formData.gender,
      goal: formData.goal,
      equipment: formData.equipment,
      fitnessLevel: formData.fitnessLevel,
      workoutDays: Number(formData.workoutDays),
      workoutDuration: Number(formData.workoutDuration),
      injuries: formData.injuries,
      preferences: formData.preferences
    };

    try {
      const response = await axios.post('https://zanefit-express-production.up.railway.app/api/workout', payload);
      setWorkoutPlan(response.data);
      setActiveTab('summary');
    } catch (error) {
      console.error('Error details:', error);
      let errorMessage = 'Failed to generate workout plan. Please try again.';
      if (error.response) {
        if (Array.isArray(error.response.data?.details)) {
          errorMessage = error.response.data.details.join(', ');
        } else if (error.response.data?.error) {
          errorMessage = error.response.data.error;
        } else if (error.response.data) {
          errorMessage = typeof error.response.data === 'string' 
            ? error.response.data 
            : JSON.stringify(error.response.data);
        }
      } else if (error.request) {
        errorMessage = 'No response received from server';
      } else {
        errorMessage = error.message;
      }
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const printPlan = () => {
    window.print();
  };

  return (
    <div>
    <div>
    <Helmet>
      <title>ZaNeFiT | Generate Your Personalized Workout Plan</title>
      <meta
        name="description"
        content="Answer a few questions to generate your free personalized workout plan tailored to your fitness goals."
      />
      <link rel="canonical" href="https://zanefit.netlify.app/" />
      <meta name="keywords" content=" free fitness, zanefit, sharonzane, zanefit workout, ZaNeFiT, health, ZaNeFit" />
      <script type="application/ld+json">
    {`
      {
        "@context": "https://schema.org",
        "@type": "WebPage",
        "name": "Personalized Workout Plan and many Other Features",
        "description": "ZaNeFiT offers free personalized workout plans tailored to your fitness goals. No fees. No fluff. Just fitness.",
        "url": "https://zanefit.netlify.app/workout-form"
      }
    `}
  </script>
    </Helmet>
    </div>
    <div className="workout-app">
      <Header/>

      <main className="app-content">
        <div className="form-section">
          <div className="form-header">
            <h1>Generate Your <span className="highlight">Personalized</span> Workout Plan</h1>
            <p className="subtitle">Answer a few questions to get a workout plan tailored to your goals and fitness level</p>
          </div>

          <form onSubmit={handleSubmit} className="workout-form">
            <div className="form-grid">
              <div className="form-card">
                <label className="input-label">
                  <span>Age *</span>
                  <input 
                    type="number" 
                    name="age" 
                    value={formData.age} 
                    onChange={handleChange} 
                    min="15" 
                    max="100" 
                    required 
                    className="form-input"
                  />
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Gender *</span>
                  <div className="select-wrapper">
                    <select 
                      name="gender" 
                      value={formData.gender} 
                      onChange={handleChange} 
                      required 
                      className="form-select"
                    >
                      <option value="male">Male</option>
                      <option value="female">Female</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Height (cm) *</span>
                  <input 
                    type="number" 
                    name="height" 
                    value={formData.height} 
                    onChange={handleChange} 
                    min="100" 
                    max="250" 
                    required 
                    className="form-input"
                  />
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Weight (kg) *</span>
                  <input 
                    type="number" 
                    name="weight" 
                    value={formData.weight} 
                    onChange={handleChange} 
                    min="30" 
                    max="200" 
                    required 
                    className="form-input"
                  />
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Goal *</span>
                  <div className="select-wrapper">
                    <select 
                      name="goal" 
                      value={formData.goal} 
                      onChange={handleChange} 
                      required 
                      className="form-select"
                    >
                      <option value="lose weight">Weight Loss</option>
                      <option value="build muscle">Build Muscle</option>
                      <option value="strength">Strength</option>
                      <option value="endurance">Endurance</option>
                    </select>
                  </div>
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Fitness Level *</span>
                  <div className="select-wrapper">
                    <select 
                      name="fitnessLevel" 
                      value={formData.fitnessLevel} 
                      onChange={handleChange} 
                      required 
                      className="form-select"
                    >
                      <option value="beginner">Beginner</option>
                      <option value="intermediate">Intermediate</option>
                      <option value="advanced">Advanced</option>
                    </select>
                  </div>
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Workout Days/Week *</span>
                  <input 
                    type="number" 
                    name="workoutDays" 
                    value={formData.workoutDays} 
                    onChange={handleChange} 
                    min="1" 
                    max="7" 
                    required 
                    className="form-input"
                  />
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Duration (min) *</span>
                  <input 
                    type="number" 
                    name="workoutDuration" 
                    value={formData.workoutDuration} 
                    onChange={handleChange} 
                    min="15" 
                    max="180" 
                    required 
                    className="form-input"
                  />
                </label>
              </div>

              <div className="form-card">
                <label className="input-label">
                  <span>Equipment *</span>
                  <div className="select-wrapper">
                    <select 
                      name="equipment" 
                      value={formData.equipment} 
                      onChange={handleChange} 
                      required 
                      className="form-select"
                    >
                      <option value="none">No Equipment</option>
                      <option value="basic">Basic Equipment</option>
                      <option value="full">Full Gym</option>
                    </select>
                  </div>
                </label>
              </div>

       
            </div>

            <div className="form-actions">
              <button type="submit" disabled={isLoading} className="submit-btn">
                {isLoading ? (
                  <>
                    <span className="spinner"></span>
                    Generating...
                  </>
                ) : (
                  'Generate My Plan'
                )}
              </button>
              {error && <div className="error-message">{error}</div>}
            </div>
          </form>
        </div>

        {workoutPlan && (
          <div className="plan-section">
            <div className="plan-header">
              <h2>Your <span className="highlight">Personalized</span> Workout Plan</h2>
              <button onClick={printPlan} className="print-btn">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M6 9V2H18V9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M6 18H4C2.89543 18 2 17.1046 2 16V11C2 9.89543 2.89543 9 4 9H20C21.1046 9 22 9.89543 22 11V16C22 17.1046 21.1046 18 20 18H18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M18 14H6V22H18V14Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
                Print Plan
              </button>
            </div>

            <div className="plan-tabs">
              <button 
                className={`tab-btn ${activeTab === 'summary' ? 'active' : ''}`}
                onClick={() => setActiveTab('summary')}
              >
                Summary
              </button>
              <button 
                className={`tab-btn ${activeTab === 'schedule' ? 'active' : ''}`}
                onClick={() => setActiveTab('schedule')}
              >
                Weekly Schedule
              </button>
              <button 
                className={`tab-btn ${activeTab === 'nutrition' ? 'active' : ''}`}
                onClick={() => setActiveTab('nutrition')}
              >
                Nutrition
              </button>
              <button 
                className={`tab-btn ${activeTab === 'recommendations' ? 'active' : ''}`}
                onClick={() => setActiveTab('recommendations')}
              >
                Recommendations
              </button>
            </div>

            {activeTab === 'summary' && (
              <div className="tab-content">
                <div className="summary-cards">
                  <div className="summary-card">
                    <h3>Plan Overview</h3>
                    <div className="summary-item">
                      <span className="summary-label">Goal:</span>
                      <span className="summary-value">{workoutPlan.planDetails?.goal}</span>
                    </div>
                    <div className="summary-item">
                      <span className="summary-label">Duration:</span>
                      <span className="summary-value">{workoutPlan.planDetails?.duration} weeks</span>
                    </div>
                    <div className="summary-item">
                      <span className="summary-label">Days Per Week:</span>
                      <span className="summary-value">{workoutPlan.planDetails?.daysPerWeek}</span>
                    </div>
                    <div className="summary-item">
                      <span className="summary-label">Session Duration:</span>
                      <span className="summary-value">{workoutPlan.planDetails?.sessionDuration} minutes</span>
                    </div>
                  </div>

                  <div className="summary-card">
                    <h3>Your Profile</h3>
                    <div className="summary-item">
                      <span className="summary-label">BMI:</span>
                      <span className="summary-value">{workoutPlan.userProfile?.bmi} ({workoutPlan.userProfile?.bmiCategory})</span>
                    </div>
                    <div className="summary-item">
                      <span className="summary-label">TDEE:</span>
                      <span className="summary-value">{workoutPlan.userProfile?.tdee} calories/day</span>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'schedule' && (
              <div className="tab-content">
                <div className="schedule-container">
                  {workoutPlan.weeklySchedule?.map((day, index) => (
                    <div key={index} className="workout-day">
                      <div className="day-header">
                        <h3>{day.dayName} (Day {day.dayNumber})</h3>
                        <div className="day-meta">
                          <span className="workout-type">{day.workoutType}</span>
                          <span className="duration">{day.durationMinutes} min</span>
                        </div>
                      </div>
                      <div className="focus-areas">
                        <strong>Focus:</strong> {day.focusAreas?.join(', ')}
                      </div>
                      
                      <div className="exercises-list">
                        <h4>Exercises</h4>
                        {day.exercises?.map((exercise, exIndex) => (
                          <div key={exIndex} className="exercise-card">
                            <div className="exercise-header">
                              <h5>{exercise.name}</h5>
                              {exercise.videoLink && (
                                <a 
                                  href={exercise.videoLink} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="video-link"
                                >
                                  View Demo
                                </a>
                              )}
                            </div>
                            <div className="exercise-details">
                              <div className="detail-item">
                                <span className="detail-label">Sets:</span>
                                <span className="detail-value">{exercise.sets}</span>
                              </div>
                              <div className="detail-item">
                                <span className="detail-label">Reps:</span>
                                <span className="detail-value">{exercise.reps}</span>
                              </div>
                              <div className="detail-item">
                                <span className="detail-label">Rest:</span>
                                <span className="detail-value">{exercise.rest}</span>
                              </div>
                            </div>
                            {exercise.notes && (
                              <div className="exercise-notes">
                                <strong>Notes:</strong> {exercise.notes}
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'nutrition' && (
              <div className="tab-content">
                <div className="nutrition-container">
                  <div className="nutrition-card">
                    <h3>Daily Nutrition</h3>
                    <div className="nutrition-item">
                      <span className="nutrition-label">Calories:</span>
                      <span className="nutrition-value">{workoutPlan.nutrition?.dailyCalories}</span>
                    </div>
                    <div className="nutrition-macros">
                      <div className="macro-item">
                        <div className="macro-label">Protein</div>
                        <div className="macro-value">{workoutPlan.nutrition?.macronutrients?.protein}</div>
                      </div>
                      <div className="macro-item">
                        <div className="macro-label">Carbs</div>
                        <div className="macro-value">{workoutPlan.nutrition?.macronutrients?.carbohydrates}</div>
                      </div>
                      <div className="macro-item">
                        <div className="macro-label">Fats</div>
                        <div className="macro-value">{workoutPlan.nutrition?.macronutrients?.fats}</div>
                      </div>
                    </div>
                  </div>

                  <div className="nutrition-tips">
                    <h3>Nutrition Tips</h3>
                    <div className="tip-item">
                      <strong>Meal Frequency:</strong> {workoutPlan.nutrition?.mealFrequency}
                    </div>
                    <div className="tip-item">
                      <strong>Hydration:</strong> {workoutPlan.nutrition?.hydration}
                    </div>
                    {workoutPlan.nutrition?.tips?.map((tip, index) => (
                      <div key={index} className="tip-item">{tip}</div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'recommendations' && (
              <div className="tab-content">
                <div className="recommendations-container">
                  <h3>Personalized Recommendations</h3>
                  <ul className="recommendations-list">
                    {workoutPlan.recommendations?.map((rec, index) => (
                      <li key={index} className="recommendation-item">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                          <path d="M22 11.08V12C21.9988 14.1564 21.3005 16.2547 20.0093 17.9818C18.7182 19.709 16.9033 20.9725 14.8354 21.5839C12.7674 22.1953 10.5573 22.1219 8.53447 21.3746C6.51168 20.6273 4.78465 19.2461 3.61096 17.4371C2.43727 15.628 1.87979 13.4881 2.02168 11.3363C2.16356 9.18455 2.99721 7.13631 4.39828 5.49706C5.79935 3.85781 7.69279 2.71537 9.79619 2.24013C11.8996 1.7649 14.1003 1.98232 16.07 2.86" stroke="#4CAF50" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                          <path d="M22 4L12 14.01L9 11.01" stroke="#4CAF50" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                        </svg>
                        {rec}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="app-footer">
        <div className="footer-content">
          <div className="footer-logo">ZaNeFiT</div>
         
          <div className="footer-copyright">
            © {new Date().getFullYear()} . All rights reserved.
          </div>
        </div>
      </footer>
    </div>
    </div>
  );
};

export default WorkoutForm;