import React, { useState } from 'react';
import './Equipment.css';
import Header from './Header'; // Import your Header component

const EquipmentSuggestions = ({ onSuggestionsLoaded }) => {
  // Organized equipment categories
  const equipmentOptions = [
    // No Equipment/Bodyweight
    { id: 'none', label: 'No Equipment', icon: '🏋️', category: 'bodyweight' },
    
    // Basic Home Equipment
    { id: 'dumbbells', label: 'Dumbbells', icon: '💪', category: 'home' },
    { id: 'resistance-bands', label: 'Resistance Bands', icon: '🧶', category: 'home' },
    { id: 'yoga-mat', label: 'Yoga Mat', icon: '🧘', category: 'home' },
    { id: 'kettlebells', label: 'Kettlebells', icon: '🔔', category: 'home' },
    { id: 'pull-up-bar', label: 'Pull-up Bar', icon: '⬆️', category: 'home' },
    { id: 'jump-rope', label: 'Jump Rope', icon: '🔄', category: 'home' },
    { id: 'stability-ball', label: 'Stability Ball', icon: '⚽', category: 'home' },
    
    // Gym Equipment
    { id: 'full-gym', label: 'Full Gym Access', icon: '🏋️‍♂️', category: 'gym' },
    { id: 'barbell', label: 'Barbell', icon: '🥇', category: 'gym' },
    { id: 'weight-plates', label: 'Weight Plates', icon: '⏹️', category: 'gym' },
    { id: 'bench', label: 'Workout Bench', icon: '🛋️', category: 'gym' },
    { id: 'cable-machine', label: 'Cable Machine', icon: '🎚️', category: 'gym' },
    { id: 'leg-press', label: 'Leg Press Machine', icon: '🦵', category: 'gym' },
    { id: 'treadmill', label: 'Treadmill', icon: '🏃‍♂️', category: 'gym' },
    { id: 'elliptical', label: 'Elliptical', icon: '🚶‍♂️', category: 'gym' },
    { id: 'rowing-machine', label: 'Rowing Machine', icon: '🚣‍♂️', category: 'gym' },
    
    // Specialized Equipment
    { id: 'trx', label: 'TRX Suspension', icon: '🪢', category: 'specialized' },
    { id: 'battle-ropes', label: 'Battle Ropes', icon: '🌊', category: 'specialized' },
    { id: 'medicine-ball', label: 'Medicine Ball', icon: '🏐', category: 'specialized' },
    { id: 'plyo-box', label: 'Plyometric Box', icon: '📦', category: 'specialized' },
    { id: 'sandbag', label: 'Sandbag', icon: '🛍️', category: 'specialized' },
    { id: 'sliders', label: 'Sliders', icon: '⏸️', category: 'specialized' },
  ];

  const [selectedEquipment, setSelectedEquipment] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [activeCategory, setActiveCategory] = useState('all');

  // Filter equipment by category
  const filteredEquipment = activeCategory === 'all' 
    ? equipmentOptions 
    : equipmentOptions.filter(equip => equip.category === activeCategory);

  const getSuggestions = async () => {
    if (selectedEquipment.length === 0) {
      alert('Please select at least one equipment option');
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch('https://zanefit-express-production.up.railway.app/api/equipment', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ equipment: selectedEquipment }),
      });
      
      const data = await response.json();
      onSuggestionsLoaded(data.exercises);
    } catch (error) {
      console.error('Error fetching suggestions:', error);
      alert('Failed to get suggestions. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const toggleEquipment = (equipmentId) => {
    const newSelection = selectedEquipment.includes(equipmentId)
      ? selectedEquipment.filter(id => id !== equipmentId)
      : [...selectedEquipment, equipmentId];
    
    setSelectedEquipment(newSelection);
  };

  return (
    <>
    <Header />
    <div className="equipment-suggestions">
    <h1>Under Development</h1>
      <h3>What equipment do you have available?</h3>
      <p className="subtext">Select all that apply</p>
      
      {/* Category Filters */}
      <div className="category-filters">
        <button 
          className={`category-btn ${activeCategory === 'all' ? 'active' : ''}`}
          onClick={() => setActiveCategory('all')}
        >
          All
        </button>
        <button 
          className={`category-btn ${activeCategory === 'bodyweight' ? 'active' : ''}`}
          onClick={() => setActiveCategory('bodyweight')}
        >
          Bodyweight
        </button>
        <button 
          className={`category-btn ${activeCategory === 'home' ? 'active' : ''}`}
          onClick={() => setActiveCategory('home')}
        >
          Home
        </button>
        <button 
          className={`category-btn ${activeCategory === 'gym' ? 'active' : ''}`}
          onClick={() => setActiveCategory('gym')}
        >
          Gym
        </button>
        <button 
          className={`category-btn ${activeCategory === 'specialized' ? 'active' : ''}`}
          onClick={() => setActiveCategory('specialized')}
        >
          Specialized
        </button>
      </div>
      
      <div className="equipment-grid">
        {filteredEquipment.map((equipment) => (
          <button
            key={equipment.id}
            className={`equipment-card ${selectedEquipment.includes(equipment.id) ? 'selected' : ''}`}
            onClick={() => toggleEquipment(equipment.id)}
            type="button"
            disabled={isLoading}
          >
            <span className="equipment-icon">{equipment.icon}</span>
            <span className="equipment-label">{equipment.label}</span>
          </button>
        ))}
      </div>

      <div className="selected-summary">
        {selectedEquipment.length > 0 && (
          <p>Selected: {selectedEquipment.length} equipment</p>
        )}
      </div>

      <button 
        onClick={getSuggestions}
        disabled={isLoading || selectedEquipment.length === 0}
        className="submit-btn"
      >
        {isLoading ? 'Loading...' : 'Get Workout Suggestions'}
      </button>
    </div>
    </>
  );
};

export default EquipmentSuggestions;