import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
  faUser, 
  faClipboardList, 
  faDumbbell, 
  faQuestionCircle,
  faHeart,
  faChartLine,
  faFire,
  faRunning,
  faUtensils
} from '@fortawesome/free-solid-svg-icons';
import './Homepage.css';
import Header from './Header'; 
import gymBackground from '../assets/gym-bg.jpg';
import { getAuth, onAuthStateChanged } from 'firebase/auth';

const HomePage = () => {
  const navigate = useNavigate();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const auth = getAuth();
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setIsAuthenticated(!!user);
    });
    return () => unsubscribe();
  }, []);

  const handleButtonClick = () => {
    navigate(isAuthenticated ? '/UserDashboard' : '/auth');
  };

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  return (
    <div className="homepage">
      <Helmet>
        <title>ZaNeFiT | Free Personalized Workout Plan</title>
        <meta name="description" content="Free personalized workout plans tailored to your fitness goals." />
        <meta name="keywords" content="free fitness, zanefit, sharonzane, zanefit workout, ZaNeFiT, health" />
      </Helmet>

      <Header isMenuOpen={isMenuOpen} toggleMenu={toggleMenu} />

      <div className="hero" style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url(${gymBackground})` }}>
        <div className="hero-content">
          <div className="hero-text">
            <h1>Transform Your Fitness Journey</h1>
            <p className="hero-subtitle">Tailored workouts. Expert nutrition. All completely free.</p>
            <button onClick={handleButtonClick} className="cta-button pulse">
              {isAuthenticated ? 'Your Dashboard' : 'Start Now - It\'s Free'}
            </button>
          </div>
          <div className="hero-stats">
            <div className="stat-item">
              <FontAwesomeIcon icon={faUser} className="stat-icon" />
              <span className="stat-number">10,000+</span>
              <span className="stat-label">Active Users</span>
            </div>
            <div className="stat-item">
              <FontAwesomeIcon icon={faFire} className="stat-icon" />
              <span className="stat-number">500,000+</span>
              <span className="stat-label">Workouts Completed</span>
            </div>
            <div className="stat-item">
              <FontAwesomeIcon icon={faHeart} className="stat-icon" />
              <span className="stat-number">100%</span>
              <span className="stat-label">Satisfaction</span>
            </div>
          </div>
        </div>
        <div className="scroll-indicator">
          <div className="mouse"></div>
        </div>
      </div>

      <section id="how-it-works" className="section">
        <div className="section-header">
          <h2>How ZaNeFiT Works</h2>
          <p className="section-subtitle">Get fit in just 3 simple steps</p>
        </div>
        <div className="steps">
          <div className="step">
            <div className="step-icon">
              <FontAwesomeIcon icon={faClipboardList} />
              <div className="step-number">1</div>
            </div>
            <h3>Get Your Plan</h3>
            <p>Answer a few questions and receive a customized workout plan designed for your goals and equipment.</p>
          </div>
          <div className="step">
            <div className="step-icon">
              <FontAwesomeIcon icon={faRunning} />
              <div className="step-number">2</div>
            </div>
            <h3>Start Training</h3>
            <p>Follow your personalized workouts with video demonstrations and detailed instructions.</p>
          </div>
          <div className="step">
            <div className="step-icon">
              <FontAwesomeIcon icon={faUtensils} />
              <div className="step-number">3</div>
            </div>
            <h3>Track Progress</h3>
            <p>Monitor your improvements with our progress tracker and adjust your plan as you get stronger.</p>
          </div>
        </div>
      </section>

      <section id="features" className="section light">
        <div className="section-header">
          <h2>Why Choose ZaNeFiT</h2>
          <p className="section-subtitle">Everything you need to succeed</p>
        </div>
        <div className="features">
          <div className="feature">
            <div className="feature-icon-container">
              <FontAwesomeIcon icon={faDumbbell} className="feature-icon" />
            </div>
            <h3>Equipment Options</h3>
            <p>Workouts tailored to the equipment you have available, whether it's a full gym or just bodyweight.</p>
          </div>
          <div className="feature">
            <div className="feature-icon-container">
              <FontAwesomeIcon icon={faChartLine} className="feature-icon" />
            </div>
            <h3>Progress Tracking</h3>
            <p>Visualize your improvements with detailed analytics and performance metrics.</p>
          </div>
          <div className="feature">
            <div className="feature-icon-container">
              <FontAwesomeIcon icon={faHeart} className="feature-icon" />
            </div>
            <h3>Health Focused</h3>
            <p>Plans designed for sustainable results and long-term health benefits.</p>
          </div>
        </div>
      </section>

      <section id="testimonials" className="section testimonial-section">
        <div className="section-header">
          <h2>Success Stories</h2>
          <p className="section-subtitle">Hear from our community</p>
        </div>
        <div className="testimonials">
          <div className="testimonial">
            <div className="testimonial-content">
              <p>"ZaNeFiT completely changed my approach to fitness. The personalized plan helped me  in Six pack 3 months!"</p>
            </div>
            <div className="testimonial-author">
              <div className="author-avatar">AB</div>
              <div className="author-info">
                <h4>J.Abishek  , MR.DenginiKota</h4>
                <p>Six pack star</p>
              </div>
            </div>
          </div>
          <div className="testimonial">
            <div className="testimonial-content">
              <p>"As a beginner, I was overwhelmed. ZaNeFiT made it simple and I've been consistent for 6 months now!"</p>
            </div>
            <div className="testimonial-author">
              <div className="author-avatar">AC</div>
              <div className="author-info">
                <h4>A.C Samuvel  , MR.Mathigiri</h4>
                <p>Gained 6kg  Muscle</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section id="why-free" className="section">
        <div className="why-free-content">
          <FontAwesomeIcon icon={faQuestionCircle} className="why-free-icon" />
          <h2>Why Is ZaNeFiT Free?</h2>
          <p>We believe everyone deserves access to quality fitness guidance regardless of their budget. Our mission is to make health and wellness accessible to all.</p>
        </div>
      </section>

      <section className="cta-section">
        <div className="cta-content">
          <h2>Ready to Transform Your Body?</h2>
          <p>Join thousands of others who've achieved their fitness goals with ZaNeFiT</p>
          <button onClick={handleButtonClick} className="cta-button">
            {isAuthenticated ? 'Continue Your Journey' : 'Get Your Free Plan Now'}
          </button>
        </div>
      </section>

      <footer className="app-footer">
        <div className="footer-content">
          <div className="footer-logo">ZaNeFiT</div>
          <div className="footer-links">
            <a href="/about">About</a>
            <a href="/contact">Contact</a>
            <a href="/privacy">Privacy</a>
            <a href="/terms">Terms</a>
          </div>
          <div className="footer-social">
            {/* Social icons would go here */}
          </div>
          <div className="footer-copyright">
            © {new Date().getFullYear()} ZaNeFiT. All rights reserved.
          </div>
        </div>
      </footer>
    </div>
  );
};

export default HomePage;