import React, { useState, useEffect } from 'react';
import { auth } from '../firebase';
import { getDatabase, ref, onValue } from 'firebase/database';
import { FiUser, FiLogOut, FiChevronDown, FiBell, FiMessageSquare, FiCheckCircle } from 'react-icons/fi';
import { RiDashboardLine } from 'react-icons/ri';
import { IoSettingsOutline } from 'react-icons/io5';
import './Header.css';
import Popup from './Popup';
import { useNavigate } from 'react-router-dom';

const Header = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [userData, setUserData] = useState(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [showSignOutPopup, setShowSignOutPopup] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const navigate = useNavigate();

  const protectedNavigate = (path) => {
    if (user) {
      navigate(path);
    } else {
      navigate('/auth');
    }
    setMenuOpen(false);
  };

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((currentUser) => {
      setUser(currentUser);
      
      if (currentUser) {
        const db = getDatabase();
        const userRef = ref(db, `users/${currentUser.uid}`);
        
        const unsubscribeUserData = onValue(userRef, (snapshot) => {
          const data = snapshot.val();
          setUserData(data);
        });

        return () => unsubscribeUserData();
      } else {
        setUserData(null);
      }
    });

    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      unsubscribe();
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
    setDropdownOpen(false);
    setSearchOpen(false);
  };

  const toggleDropdown = () => {
    setDropdownOpen(!dropdownOpen);
    setMenuOpen(false);
    setSearchOpen(false);
  };

  const handleSignOut = async () => {
    try {
      await auth.signOut();
      setShowSignOutPopup(true);
      setMenuOpen(false);
      setDropdownOpen(false);

      setTimeout(() => {
        navigate('/');
        setShowSignOutPopup(false);
      }, 1000);
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  const getUserInitials = () => {
    if (!userData) return '';
    
    if (userData.name) {
      const names = userData.name.split(' ');
      if (names.length > 1) {
        return `${names[0][0]}${names[1][0]}`.toUpperCase();
      }
      return names[0][0].toUpperCase();
    }
    
    return user?.email?.[0]?.toUpperCase() || '';
  };

  const getUserName = () => {
    if (userData) {
      if (userData.username) return userData.username;
      if (userData.name) return userData.name;
      if (userData.firstName && userData.lastName) {
        return `${userData.firstName} ${userData.lastName}`;
      }
      if (userData.firstName) return userData.firstName;
    }
    
    return user?.email?.split('@')[0] || '';
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchQuery)}`);
      setSearchQuery('');
      setSearchOpen(false);
    }
  };

  return (
    <header className={`app-header ${scrolled ? 'scrolled' : ''}`}>
      <div className="header-container">
        <a href="/" className="logo-link">
          <div className="logo">
            <span className="logo-highlight">ZaNeFiT</span>
            <span className="logo-tagline">FITNESS REDEFINED</span>
          </div>
        </a>
        
        <div className="header-right">
          <nav className="desktop-nav">
            <button className="nav-link" onClick={() => protectedNavigate('/featuresList')}>
              Features
            </button>
            <button className="nav-link" onClick={() => protectedNavigate('/workout-form')}>
              Workout Plan
            </button>
            <button className="nav-link" onClick={() => protectedNavigate('/progress')}>
              Progress
            </button>
          </nav>

          <div className="header-actions">
            {user ? (
              <>
                <button className="icon-button notification-button">
                  <FiBell size={20} />
                  <span className="notification-badge">3</span>
                </button>
                <button className="icon-button">
                  <FiMessageSquare size={20} />
                </button>

                <div className="user-dropdown-container">
                  <button 
                    className="user-profile" 
                    onClick={toggleDropdown}
                    aria-expanded={dropdownOpen}
                    aria-label="User menu"
                  >
                    <div className="avatar-circle">
                      {getUserInitials()}
                    </div>
                    <span className="user-name">
                      {getUserName()}
                    </span>
                    <FiChevronDown className={`dropdown-arrow ${dropdownOpen ? 'open' : ''}`} />
                  </button>

                  {dropdownOpen && (
                    <div className="dropdown-menu">
                      <a href="/profile" className="dropdown-item">
                        <FiUser className="dropdown-icon" />
                        <span>My Profile</span>
                      </a>
                      <a href="/UserDashboard" className="dropdown-item">
                        <RiDashboardLine className="dropdown-icon" />
                        <span>Dashboard</span>
                      </a>
                      <a href="/settings" className="dropdown-item">
                        <IoSettingsOutline className="dropdown-icon" />
                        <span>Settings</span>
                      </a>
                      <div className="dropdown-divider"></div>
                      <button className="dropdown-item" onClick={handleSignOut}>
                        <FiLogOut className="dropdown-icon" />
                        <span>Sign Out</span>
                      </button>
                    </div>
                  )}
                </div>
              </>
            ) : (
              <div className="auth-buttons">
                <button 
                  className="secondary-button" 
                  onClick={() => navigate('/login')}
                >
                  Log In
                </button>
                <button 
                  className="primary-button" 
                  onClick={() => navigate('/signup')}
                >
                  Sign Up
                </button>
              </div>
            )}

            <button 
              className="menu-toggle" 
              onClick={toggleMenu} 
              aria-label="Menu"
              aria-expanded={menuOpen}
            >
              <div className={`menu-icon ${menuOpen ? 'open' : ''}`}>
                <span></span>
                <span></span>
                <span></span>
              </div>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`mobile-menu ${menuOpen ? 'active' : ''}`}>
        <div className="mobile-menu-header">
          {user ? (
            <div className="mobile-user-info">
              <div className="avatar-circle large">
                {getUserInitials()}
              </div>
              <div className="mobile-user-details">
                <h4>{getUserName()}</h4>
                <p>{user?.email}</p>
              </div>
            </div>
          ) : (
            <div className="mobile-auth-prompt">
              <h3>Join ZaNeFiT</h3>
              <p>Start your fitness journey today</p>
            </div>
          )}
        </div>

        <nav className="mobile-nav">
          <button className="mobile-nav-link" onClick={() => protectedNavigate('/workout-form')}>
            <span>Workouts</span>
          </button>
          <button className="mobile-nav-link" onClick={() => protectedNavigate('/nutrition')}>
            <span>Nutrition</span>
          </button>
          <button className="mobile-nav-link" onClick={() => protectedNavigate('/progress')}>
            <span>Progress</span>
          </button>

          {user ? (
            <>
              <div className="mobile-nav-divider"></div>
              <button className="mobile-nav-link" onClick={() => {
                navigate('/profile');
                setMenuOpen(false);
              }}>
                <span>My Profile</span>
              </button>
              <button className="mobile-nav-link" onClick={() => {
                navigate('/dashboard');
                setMenuOpen(false);
              }}>
                <span>Dashboard</span>
              </button>
              <button className="mobile-nav-link" onClick={() => {
                navigate('/settings');
                setMenuOpen(false);
              }}>
                <span>Settings</span>
              </button>
              <button className="sign-out-button" onClick={handleSignOut}>
                <span>Sign Out</span>
              </button>
            </>
          ) : (
            <div className="mobile-auth-buttons">
              <button 
                className="secondary-button full-width" 
                onClick={() => {
                  navigate('/login');
                  setMenuOpen(false);
                }}
              >
                Log In
              </button>
              <button 
                className="primary-button full-width" 
                onClick={() => {
                  navigate('/signup');
                  setMenuOpen(false);
                }}
              >
                Sign Up
              </button>
            </div>
          )}
        </nav>
      </div>

      {/* Popup for Sign Out */}
      <Popup
        show={showSignOutPopup}
        onClose={() => setShowSignOutPopup(false)}
        title="Signed Out"
        message="You have been signed out. Redirecting to the homepage..."
        icon={<FiCheckCircle />}
        color="#10b981"
      />
    </header>
  );
};

export default Header;