import React, { useState, useEffect } from 'react';
import { 
  FaUsers, 
  FaDumbbell, 
  FaChartLine, 
  FaClipboardList, 
  FaCog,
  FaSearch,
  FaBell,
  FaUserCircle
} from 'react-icons/fa';
import './Admin.css'; // Assuming you have a CSS file for styling

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [workouts, setWorkouts] = useState([]);
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeUsers: 0,
    workoutsCreated: 0,
    equipmentOptions: 0
  });

  // Mock data fetch
  useEffect(() => {
    // In a real app, you would fetch this from your API
    setUsers([
      { id: 1, name: 'John Doe', email: 'john@example.com', joined: '2023-01-15', status: 'active' },
      { id: 2, name: 'Jane Smith', email: 'jane@example.com', joined: '2023-02-20', status: 'active' },
      { id: 3, name: 'Mike Johnson', email: 'mike@example.com', joined: '2023-03-10', status: 'inactive' }
    ]);

    setWorkouts([
      { id: 1, name: 'Beginner Full Body', category: 'Strength', equipment: 'Dumbbells', created: '2023-04-05' },
      { id: 2, name: 'Yoga Flow', category: 'Flexibility', equipment: 'Yoga Mat', created: '2023-04-12' },
      { id: 3, name: 'HIIT Circuit', category: 'Cardio', equipment: 'None', created: '2023-04-18' }
    ]);

    setStats({
      totalUsers: 1243,
      activeUsers: 892,
      workoutsCreated: 56,
      equipmentOptions: 24
    });
  }, []);

  const renderTabContent = () => {
    switch(activeTab) {
      case 'users':
        return (
          <div className="users-section">
            <h2>User Management</h2>
            <div className="search-bar">
              <FaSearch />
              <input type="text" placeholder="Search users..." />
            </div>
            <table className="users-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Joined</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {users.map(user => (
                  <tr key={user.id}>
                    <td>{user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.email}</td>
                    <td>{user.joined}</td>
                    <td>
                      <span className={`status-badge ${user.status}`}>
                        {user.status}
                      </span>
                    </td>
                    <td>
                      <button className="action-btn edit">Edit</button>
                      <button className="action-btn delete">Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
      case 'workouts':
        return (
          <div className="workouts-section">
            <h2>Workout Management</h2>
            <div className="workout-actions">
              <button className="add-btn">+ Add New Workout</button>
            </div>
            <div className="workouts-grid">
              {workouts.map(workout => (
                <div key={workout.id} className="workout-card">
                  <h3>{workout.name}</h3>
                  <p><strong>Category:</strong> {workout.category}</p>
                  <p><strong>Equipment:</strong> {workout.equipment}</p>
                  <p><strong>Created:</strong> {workout.created}</p>
                  <div className="workout-actions">
                    <button className="edit-btn">Edit</button>
                    <button className="delete-btn">Delete</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'equipment':
        return (
          <div className="equipment-section">
            <h2>Equipment Management</h2>
            <div className="equipment-form">
              <input type="text" placeholder="Equipment name" />
              <input type="text" placeholder="Icon (emoji)" />
              <button className="add-btn">Add Equipment</button>
            </div>
            <div className="equipment-list">
              {/* This would map through equipment options */}
              <div className="equipment-item">
                <span className="equipment-icon">💪</span>
                <span className="equipment-name">Dumbbells</span>
                <button className="delete-btn">Delete</button>
              </div>
              <div className="equipment-item">
                <span className="equipment-icon">🧘</span>
                <span className="equipment-name">Yoga Mat</span>
                <button className="delete-btn">Delete</button>
              </div>
            </div>
          </div>
        );
      case 'analytics':
        return (
          <div className="analytics-section">
            <h2>Site Analytics</h2>
            <div className="stats-grid">
              <div className="stat-card">
                <h3>Total Users</h3>
                <p>{stats.totalUsers}</p>
              </div>
              <div className="stat-card">
                <h3>Active Users</h3>
                <p>{stats.activeUsers}</p>
              </div>
              <div className="stat-card">
                <h3>Workouts Created</h3>
                <p>{stats.workoutsCreated}</p>
              </div>
              <div className="stat-card">
                <h3>Equipment Options</h3>
                <p>{stats.equipmentOptions}</p>
              </div>
            </div>
            <div className="chart-placeholder">
              <p>User Growth Chart (Last 30 Days)</p>
              {/* In a real app, you would use a charting library here */}
              <div className="mock-chart"></div>
            </div>
          </div>
        );
      default:
        return (
          <div className="dashboard-section">
            <h2>Dashboard Overview</h2>
            <div className="welcome-banner">
              <h3>Welcome back, Admin!</h3>
              <p>Here's what's happening with your site today.</p>
            </div>
            <div className="stats-grid">
              <div className="stat-card">
                <h3>Total Users</h3>
                <p>{stats.totalUsers}</p>
              </div>
              <div className="stat-card">
                <h3>Active Users</h3>
                <p>{stats.activeUsers}</p>
              </div>
              <div className="stat-card">
                <h3>Workouts Created</h3>
                <p>{stats.workoutsCreated}</p>
              </div>
              <div className="stat-card">
                <h3>Equipment Options</h3>
                <p>{stats.equipmentOptions}</p>
              </div>
            </div>
            <div className="recent-activity">
              <h3>Recent Activity</h3>
              <ul>
                <li>New user registered: Jane Smith</li>
                <li>Workout "HIIT Circuit" was created</li>
                <li>5 users completed workouts today</li>
              </ul>
            </div>
          </div>
        );
    }
  };

  return (
    <div className="admin-dashboard">
      {/* Sidebar */}
      <div className="sidebar">
        <div className="logo">ZaNeFiT Admin</div>
        <nav>
          <ul>
            <li 
              className={activeTab === 'dashboard' ? 'active' : ''}
              onClick={() => setActiveTab('dashboard')}
            >
              <FaChartLine /> Dashboard
            </li>
            <li 
              className={activeTab === 'users' ? 'active' : ''}
              onClick={() => setActiveTab('users')}
            >
              <FaUsers /> Users
            </li>
            <li 
              className={activeTab === 'workouts' ? 'active' : ''}
              onClick={() => setActiveTab('workouts')}
            >
              <FaDumbbell /> Workouts
            </li>
            <li 
              className={activeTab === 'equipment' ? 'active' : ''}
              onClick={() => setActiveTab('equipment')}
            >
              <FaClipboardList /> Equipment
            </li>
            <li 
              className={activeTab === 'analytics' ? 'active' : ''}
              onClick={() => setActiveTab('analytics')}
            >
              <FaChartLine /> Analytics
            </li>
            <li 
              className={activeTab === 'settings' ? 'active' : ''}
              onClick={() => setActiveTab('settings')}
            >
              <FaCog /> Settings
            </li>
          </ul>
        </nav>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {/* Top Navigation */}
        <div className="top-nav">
          <div className="search-bar">
            <FaSearch />
            <input type="text" placeholder="Search..." />
          </div>
          <div className="admin-actions">
            <button className="notification-btn">
              <FaBell />
              <span className="badge">3</span>
            </button>
            <div className="admin-profile">
              <FaUserCircle />
              <span>Admin</span>
            </div>
          </div>
        </div>

        {/* Content Area */}
        <div className="content-area">
          {renderTabContent()}
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;